{
  "category_edits": [
    {
      "category": "architecture_interaction",
      "rationale": "Scale every causal convolution block's residual update by 0.5 across all four category models to test whether damping preserves useful input information. Keep all other model and training settings fixed. The predictor imports the modified architecture; matching metadata verifies residual-scale compatibility.",
      "edits": [
        {
          "find": "        return residual + y",
          "replace": "        return residual + 0.5 * y"
        },
        {
          "find": "            \"sequence_readout\": \"causal_recent4_blend_0.2\",\n",
          "replace": "            \"sequence_readout\": \"causal_recent4_blend_0.2\",\n            \"residual_scale\": 0.5,\n"
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"causal_recent4_blend_0.2\":\n            raise RuntimeError(f\"Incompatible sequence readout metadata for {ds}\")\n",
          "replace": "        if meta.get(\"sequence_readout\") != \"causal_recent4_blend_0.2\":\n            raise RuntimeError(f\"Incompatible sequence readout metadata for {ds}\")\n        if meta.get(\"residual_scale\") != 0.5:\n            raise RuntimeError(f\"Incompatible residual scale metadata for {ds}\")\n"
        }
      ]
    }
  ],
  "change_summary": "Apply fixed 0.5 residual scaling to every NextItNet block and record/check compatibility in the embedded predictor writer, retaining one model per category."
}
